from pathlib import Path
from datetime import datetime
import shutil

root=Path.cwd()
page=root/'src/app/(app)/decisiones/page.tsx'
client=root/'src/app/(app)/decisiones/DecisionesPanel.tsx'
css=root/'src/app/globals.css'
if not page.exists() or not css.exists():
    raise SystemExit('Ejecuta desde la raíz del repositorio PANIA.')
marker='/* PANIA DECISIONES V4 REFERENCIA VISUAL */'
if marker in css.read_text():
    print('Decisiones V4 ya está instalado. No se duplicó.'); raise SystemExit(0)
backup=root/'respaldos'/('decisiones_v4_'+datetime.now().strftime('%Y%m%d_%H%M%S'))
backup.mkdir(parents=True,exist_ok=True)
shutil.copy2(page,backup/'page.tsx.bak')
shutil.copy2(css,backup/'globals.css.bak')
if client.exists(): shutil.copy2(client,backup/'DecisionesPanel.tsx.bak')
page.write_text('''import {crearClienteServidor} from '@/lib/supabase/server';
import {requerirSesion} from '@/lib/sesion';
import DecisionesPanel from './DecisionesPanel';
export default async function Decisiones(){
 const {perfil}=await requerirSesion();
 if(!['dueno','administrador','contador'].includes(perfil.rol))return <section className="panel"><h2>Sin acceso</h2></section>;
 const sb=await crearClienteServidor();
 const [{data:r},{data:s}]=await Promise.all([
  sb.from('v_recomendaciones_pania').select('*').order('prioridad').order('impacto_estimado',{ascending:false}),
  sb.from('sucursales').select('id,nombre')
 ]);
 const sm=new Map((s??[]).map((x:any)=>[x.id,x.nombre]));
 const rows=(r??[]).map((x:any)=>({
  tipo:String(x.tipo??''), prioridad:Number(x.prioridad??99),
  severidad:String(x.severidad??''), hallazgo:String(x.hallazgo??''),
  evidencia:String(x.evidencia??''), recomendacion:String(x.recomendacion??''),
  impacto:Number(x.impacto_estimado??0), ruta:String(x.ruta_accion??''),
  sucursal:x.sucursal_id?String(sm.get(x.sucursal_id)??'Sucursal'):''
 }));
 return <DecisionesPanel rows={rows}/>;
}
''')
client.write_text('''\'use client\';
import {useMemo,useState} from 'react';
type R={tipo:string;prioridad:number;severidad:string;hallazgo:string;evidencia:string;recomendacion:string;impacto:number;ruta:string;sucursal:string};
type G=R&{cantidad:number};
const mx=(n:number)=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN',maximumFractionDigits:0}).format(n||0);
const nivel=(r:R)=>r.prioridad===1?'Crítica':r.prioridad===2?'Alta':r.prioridad===3?'Media':'Informativa';
export default function DecisionesPanel({rows}:{rows:R[]}){
 const [filtro,setFiltro]=useState('Todas');const [buscar,setBuscar]=useState('');const [tipo,setTipo]=useState('Todos');
 const grupos=useMemo(()=>{const m=new Map<string,G>();for(const x of rows){const k=[x.tipo,x.prioridad,x.hallazgo,x.evidencia,x.recomendacion,x.ruta,x.sucursal].join('||');const old=m.get(k);if(old){old.cantidad++;old.impacto=Math.max(old.impacto,x.impacto)}else m.set(k,{...x,cantidad:1})}return [...m.values()].sort((a,b)=>a.prioridad-b.prioridad||b.impacto-a.impacto)},[rows]);
 const crit=grupos.filter(x=>x.prioridad===1).length,alt=grupos.filter(x=>x.prioridad===2).length,med=grupos.filter(x=>x.prioridad===3).length,otro=grupos.length-crit-alt-med;
 const impacto=grupos.reduce((a,x)=>a+Math.max(0,x.impacto),0);const top=grupos.slice(0,3);
 const visibles=grupos.filter(x=>(filtro==='Todas'||nivel(x)===filtro)&&(tipo==='Todos'||x.tipo===tipo)&&[x.hallazgo,x.evidencia,x.recomendacion,x.sucursal].join(' ').toLowerCase().includes(buscar.toLowerCase()));
 const tipos=[...new Set(grupos.map(x=>x.tipo).filter(Boolean))];
 const sum=grupos.length||1;const p1=crit/sum*100,p2=alt/sum*100,p3=med/sum*100;
 return <div className="dv4">
 <header className="dv4-hero"><div><span className="dv4-kicker">INTELIGENCIA PANIA</span><h1>Decisiones IA</h1><p>Recomendaciones generadas con datos reales de tu negocio.</p><p>Analiza qué revisar, qué corregir y qué hacer después.</p></div><div className="dv4-hero-note"><span className="dv4-chef">👨‍🍳</span><div><strong>PANIA analiza tu negocio en modo lectura</strong><p>Te muestra oportunidades, riesgos y acciones para mejorar resultados.</p></div></div></header>
 <section className="dv4-kpis"><div className="dv4-kpi verde"><span className="dv4-kpi-icon">▤</span><div><strong>{rows.length}</strong><span>Recomendaciones de origen</span></div></div><div className="dv4-kpi naranja"><span className="dv4-kpi-icon">⚠</span><div><strong>{crit}</strong><span>Hallazgos críticos distintos</span></div></div><div className="dv4-kpi azul"><span className="dv4-kpi-icon">▥</span><div><strong>{mx(impacto)}</strong><span>Impacto referencial sin duplicados</span></div></div><div className="dv4-kpi violeta"><span className="dv4-kpi-icon">◎</span><div><strong>{grupos.length}</strong><span>Hallazgos diferentes</span></div></div></section>
 <section className="dv4-main"><article className="dv4-panel"><div className="dv4-section-head"><div><span className="dv4-kicker">TU PLAN DE ACCIÓN</span><h2>💡 Recomendaciones principales</h2><p>Las tres prioridades por urgencia e impacto.</p></div><a href="#dv4-todas" className="dv4-ghost">Ver todas →</a></div><div className="dv4-top">{top.length?top.map((x,i)=><div className="dv4-action" key={i}><span className="dv4-num">{i+1}</span><div className="dv4-action-copy"><span className={'dv4-pill '+(x.prioridad===1?'roja':'ambar')}>{nivel(x)}</span><strong>{x.recomendacion||x.hallazgo}</strong><p>{x.hallazgo}</p><small>{x.evidencia}</small></div><div className="dv4-impact"><span>Impacto referencial</span><strong>{mx(x.impacto)}</strong></div>{x.ruta.startsWith('/')?<a className="dv4-btn" href={x.ruta}>Revisar evidencia →</a>:<span className="dv4-no-link">Sin enlace</span>}</div>):<p>No hay recomendaciones pendientes.</p>}</div></article>
 <aside className="dv4-panel"><div className="dv4-section-head"><div><h2>▥ Distribución de recomendaciones</h2><p>Hallazgos distintos por prioridad</p></div></div><div className="dv4-chart-area"><div className="dv4-donut" style={{background:`conic-gradient(#ef5265 0 ${p1}%, #ffb63f ${p1}% ${p1+p2}%, #24966d ${p1+p2}% ${p1+p2+p3}%, #aab3b7 ${p1+p2+p3}% 100%)`}}><div><strong>{grupos.length}</strong><span>total</span></div></div><div className="dv4-legend">{[['Críticas',crit,'#ef5265'],['Altas',alt,'#ffb63f'],['Medias',med,'#24966d'],['Otras',otro,'#aab3b7']].map(([name,n,color])=><div key={String(name)}><i style={{background:String(color)}}/ ><span>{name}</span><strong>{n}</strong><small>{Math.round(Number(n)/sum*100)}%</small></div>)}</div></div><div className="dv4-summary">◎ Las primeras tres recomendaciones suman <strong>{mx(top.reduce((a,x)=>a+Math.max(0,x.impacto),0))}</strong> de impacto referencial, no de utilidad garantizada.</div></aside></section>
 <section className="dv4-panel dv4-all" id="dv4-todas"><div className="dv4-section-head"><div><span className="dv4-kicker">SEGUIMIENTO</span><h2>☷ Todas las recomendaciones</h2><p>Explora los hallazgos agrupados sin eliminar registros originales.</p></div><div className="dv4-filters"><select aria-label="Filtrar prioridad" value={filtro} onChange={e=>setFiltro(e.target.value)}>{['Todas','Crítica','Alta','Media','Informativa'].map(x=><option key={x}>{x}</option>)}</select><select aria-label="Filtrar tipo" value={tipo} onChange={e=>setTipo(e.target.value)}><option>Todos</option>{tipos.map(x=><option key={x}>{x}</option>)}</select><input aria-label="Buscar recomendación" placeholder="Buscar recomendación..." value={buscar} onChange={e=>setBuscar(e.target.value)}/></div></div><div className="dv4-table-wrap"><table><thead><tr><th>#</th><th>Prioridad</th><th>Hallazgo</th><th>Evidencia</th><th>Impacto</th><th>Recomendación</th><th>Acción</th></tr></thead><tbody>{visibles.map((x,i)=><tr key={i}><td>{i+1}</td><td><span className={'dv4-pill '+(x.prioridad===1?'roja':'ambar')}>{nivel(x)}</span></td><td><strong>{x.hallazgo}</strong>{x.cantidad>1&&<small className="dv4-count">{x.cantidad} registros similares</small>}</td><td>{x.evidencia}</td><td><strong>{mx(x.impacto)}</strong></td><td>{x.recomendacion}</td><td>{x.ruta.startsWith('/')?<a href={x.ruta}>Abrir →</a>:'—'}</td></tr>)}</tbody></table>{!visibles.length&&<p className="dv4-empty">No hay resultados con estos filtros.</p>}</div><p className="dv4-disclaimer">Análisis de solo lectura. Los impactos son referenciales y pueden solaparse entre hallazgos distintos; no representan ahorro garantizado.</p></section>
 </div>
}
''')
css.write_text(css.read_text()+'''\n/* PANIA DECISIONES V4 REFERENCIA VISUAL */
.dv4{width:100%;max-width:none;display:grid;gap:18px;color:#102c2a}.dv4 *{box-sizing:border-box}.dv4-hero{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.dv4-hero h1{font-size:clamp(28px,3vw,42px);margin:3px 0 5px;color:#092f2b}.dv4-hero p{margin:4px 0;color:#52636b}.dv4-kicker{font-size:11px;font-weight:900;letter-spacing:.11em;color:#08745f}.dv4-hero-note{display:flex;align-items:center;gap:14px;padding:12px 20px;border-radius:16px;background:#e9f3ee;max-width:435px}.dv4-hero-note p{font-size:13px}.dv4-chef{font-size:55px}.dv4-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.dv4-kpi{display:flex;align-items:center;gap:15px;min-height:106px;padding:18px;border:1px solid #dde9e2;border-radius:17px;background:#f3faf7}.dv4-kpi.naranja{background:#fff7ef;border-color:#f6e3d1}.dv4-kpi.azul{background:#eff8ff;border-color:#d9eafa}.dv4-kpi.violeta{background:#f7f4ff;border-color:#e9e3fb}.dv4-kpi-icon{font-size:27px;display:grid;place-items:center;width:55px;height:55px;flex-shrink:0;border-radius:50%;background:#e0f1e7;color:#09664c}.dv4-kpi.naranja .dv4-kpi-icon{background:#ffead9;color:#d4520b}.dv4-kpi.azul .dv4-kpi-icon{background:#dceeff;color:#0870ba}.dv4-kpi.violeta .dv4-kpi-icon{background:#e9e2ff;color:#4d2caa}.dv4-kpi strong{display:block;font-size:clamp(22px,2.1vw,32px);line-height:1.2;color:#0b2729}.dv4-kpi span:last-child{font-size:13px}.dv4-main{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(320px,1fr);gap:15px;align-items:stretch}.dv4-panel{background:#fff;border:1px solid #e0e8e2;border-radius:17px;padding:18px;box-shadow:0 5px 18px #19372a0a;min-width:0}.dv4-section-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:15px}.dv4-section-head h2{margin:4px 0;font-size:20px;color:#132d2b}.dv4-section-head p{margin:0;color:#687780;font-size:13px}.dv4-ghost{padding:10px 14px;border:1px solid #c9e3d9;border-radius:10px;color:#08644f;font-weight:800;text-decoration:none}.dv4-top{display:grid;gap:9px}.dv4-action{display:grid;grid-template-columns:42px minmax(0,1fr) 130px 154px;align-items:center;gap:12px;padding:14px;border:1px solid #e4ebe7;border-radius:12px}.dv4-num{display:grid;place-items:center;background:#075b49;color:#fff;width:36px;height:36px;border-radius:50%;font-weight:900}.dv4-action-copy strong{display:block;font-size:13px;line-height:1.4}.dv4-action-copy p,.dv4-action-copy small{display:block;color:#586b73;font-size:12px;margin:4px 0}.dv4-pill{display:inline-block;width:max-content;border-radius:20px;padding:4px 9px;font-size:11px;font-weight:800;background:#eaf0ee;color:#52646b;margin-bottom:5px}.dv4-pill.roja{background:#ffe1e5;color:#ba263a}.dv4-pill.ambar{background:#fff0d5;color:#9b5b0a}.dv4-impact{padding:12px;border-radius:10px;background:#f2f8f5}.dv4-impact span{display:block;font-size:11px;color:#64777b}.dv4-impact strong{color:#075b49;font-size:19px}.dv4-btn{background:#065b4a;color:white!important;padding:13px 10px;text-align:center;border-radius:9px;font-size:12px;font-weight:800;text-decoration:none}.dv4-no-link{font-size:12px;color:#889}.dv4-chart-area{display:flex;align-items:center;justify-content:center;gap:25px;min-height:235px}.dv4-donut{width:178px;height:178px;border-radius:50%;display:grid;place-items:center;flex-shrink:0}.dv4-donut>div{width:105px;height:105px;border-radius:50%;background:#fff;display:flex;flex-direction:column;align-items:center;justify-content:center}.dv4-donut strong{font-size:27px}.dv4-donut span{font-size:13px;color:#718080}.dv4-legend{flex:1;min-width:140px}.dv4-legend>div{display:grid;grid-template-columns:12px 1fr auto 36px;align-items:center;gap:8px;margin:15px 0;font-size:13px}.dv4-legend i{width:12px;height:12px;border-radius:4px}.dv4-legend small{color:#79878b;text-align:right}.dv4-summary{padding:17px;background:#eff7f3;border-radius:12px;font-size:13px;line-height:1.5}.dv4-summary strong{color:#006149}.dv4-filters{display:flex;gap:8px;flex-wrap:wrap}.dv4-filters select,.dv4-filters input{width:auto;min-width:130px;max-width:250px;padding:11px;border:1px solid #dae4df;border-radius:10px;background:#fff;font:inherit;font-size:12px}.dv4-table-wrap{overflow-x:auto}.dv4-table-wrap table{width:100%;border-collapse:collapse;font-size:12px}.dv4-table-wrap th{background:#f7faf8;color:#627276;text-align:left}.dv4-table-wrap th,.dv4-table-wrap td{padding:12px;border-bottom:1px solid #e5ece8;vertical-align:middle}.dv4-table-wrap td a{color:#006c51;font-weight:800}.dv4-count{display:block;color:#7a8886;margin-top:4px}.dv4-empty{padding:15px}.dv4-disclaimer{font-size:12px;color:#74817e;margin:14px 0 0}@media(max-width:1200px){.dv4-kpis{grid-template-columns:repeat(2,minmax(0,1fr))}.dv4-main{grid-template-columns:1fr}.dv4-action{grid-template-columns:42px minmax(0,1fr) 130px 150px}}@media(max-width:720px){.dv4-kpis{grid-template-columns:1fr}.dv4-action{grid-template-columns:36px 1fr}.dv4-impact,.dv4-btn{grid-column:2}.dv4-chart-area{flex-wrap:wrap}.dv4-panel{padding:13px}.dv4-filters{width:100%}.dv4-filters input{flex:1}}\n''')
print('DECISIONES V4 INSTALADO. Respaldo:',backup)
print('Archivos: decisiones/page.tsx, decisiones/DecisionesPanel.tsx, globals.css')
print('Ahora ejecuta: npm run build')
